def is_costas(x):
    n=len(x)
    if sorted(x)!=list(range(n)): return False, 'not perm'
    seen=set()
    for i in range(n):
        for j in range(i+1,n):
            v=(x[j]-x[i], j-i)
            if v in seen:
                return False, (v,i,j)
            seen.add(v)
    return True, None
p=17; g=3
x=[pow(g,i,p)-1 for i in range(1,p)]
